    qcopy(position, moby + 0x10);
    position[3] = 1.0f;
    first.tex = ((long (*)(int))GetEffectTex)(0x2C);
    first.unk80 = 0xFF9000000260L;
    first.unk70 = 0;
    second.tex = ((long (*)(int))GetEffectTex)(0x2C);
