/* Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/shared/gameplay/entities/00278fd8.c, FUN_L15_002bddb0. */
void MovingMobyUpdate(struct Moby *moby) {
    MovingMobyVars *vars = (MovingMobyVars *)moby->pvars;
    Vec4 offset;
    Vec4 next;
    f32 step;
    f32 magnitude;
    f32 travel;
    s32 reversed;
    s32 next_state;

    reversed = moby->oclass == 0xc4 || moby->oclass == 0x7a6;
    if (vars->trigger == -1 &&
        (vars->start_volume == -1 || vars->stop_volume == -1)) {
        DeleteMoby(moby);
        return;
    }

    switch (moby->state) {
    case 0:
        vars->origin.q = *(u128_BEFF8 *)&moby->pos;
        if (vars->trigger != 0) {
            moby->state = 1;
            return;
        }
        moby->state = 4;
        return;
    case 1:
        if (((struct Moby *)(quartu_moby_array + vars->trigger * 0x100))->state != 4)
            return;
        if (reversed)
            Moby_PlaySound(0, 0, (int)moby);
        moby->state = 2;
        break;
    case 2:
        {
        union { u32 bits; f32 value; } triple;
        f32 increment;
        f32 scale;
        travel = vars->travel;
        increment = (moby->scale * 3.0f / moby->pclass->scale) / 3.0f * g_frame_time;
        increment = reversed ? -increment : increment;
        vars->travel = travel + increment;
        offset.f[0] = FastCos(moby->rot.z) * vars->travel;
        offset.f[1] = FastSin(moby->rot.z) * vars->travel;
        offset.f[2] = 0.0f;
        FastVecAdd(&next, &vars->origin, &offset);
        *(u128_BEFF8 *)&moby->pos = next.q;
        magnitude = FastAbsF(vars->travel);
        scale = moby->scale;
        triple.bits = 0x40400000;
        __builtin_memcpy(&step, &triple.bits, sizeof(step));
        step = step + 0.0f;
        if (!(scale * step / moby->pclass->scale < magnitude))
            return;
        if (vars->trigger != -1) {
            moby->state = 3;
            return;
        }
        moby->state = 5;
        return;
        }
    case 4:
        vars->travel = 0.0f;
        if (!is_point_inside_clip_volume(&g_hero.motion.pos, vars->start_volume))
            return;
        if (reversed)
            Moby_PlaySound(0, 0, (int)moby);
        moby->state = 2;
        break;
    case 5:
        if (is_point_inside_clip_volume(&g_hero.motion.pos, vars->stop_volume))
            return;
        if (reversed)
            Moby_PlaySound(0, 0, (int)moby);
        moby->state = 6;
        break;
    case 6:
        {
        f32 old_travel;
        f32 new_travel;
        magnitude = FastAbsF(vars->travel);
        step = (moby->scale * 3.0f / moby->pclass->scale) / 3.0f * g_frame_time;
        if (step < magnitude) {
            old_travel = vars->travel;
            if (reversed) {
                f32 reverse_step = -step;
                new_travel = old_travel - reverse_step;
            } else {
                new_travel = old_travel - step;
            }
            vars->travel = new_travel;
        } else {
            vars->travel = 0.0f;
        }
        offset.f[0] = FastCos(moby->rot.z) * vars->travel;
        offset.f[1] = FastSin(moby->rot.z) * vars->travel;
        offset.f[2] = 0.0f;
        FastVecAdd(&next, &vars->origin, &offset);
        *(u128_BEFF8 *)&moby->pos = next.q;
        if (vars->travel != 0.0f)
            return;
        moby->state = 4;
        break;
        }
    }
}

