/* Sentrybot alarm update (moby class 408, levels 15 and 17): turn, watch for the hero, raise the alarm. */
void SentrybotAlarmUpdate(Moby *m) {
    L15AlarmData *d = (void *)m->pvars;
    float f;
    int r;

    switch (m->state) {
    case 0: {
        int mode = d->mode;

        D_L15_00161B3C_gp = 0;
        D_L15_00161B40_gp = 0;
        D_L15_00161B44_gp = 0;
        if (mode == 2) {
            m->state = 6;
            if (m->prev_seq != 4)
                MobyBlendAnimation(m, 4, 0, 0);
        } else {
            m->state = 3;
            if (m->prev_seq != 2)
                MobyBlendAnimation(m, 2, 0, 0);
        }
        break;
    }
    case 1:
        f = FastSin(d->f14);
        r = FastTweenColor(0x801414BC, 0x801414DC, (f + 1.0f) * 0.5f);
        m->glow_color = r;
        d->f14 = FastAddRots(d->f14, g_frame_time * 6.2831855f);
        if (!d->f8)
            goto tail;
        if (quartu_game_mode == 2)
            break;
        if (d->mode != 1) {
            m->state = 5;
            break;
        }
        m->state = 6;
        if (m->prev_seq != 4)
            MobyBlendAnimation(m, 4, 0, scale_ticks(30));
        break;
    case 2:
        if (m->anim_flags & 2) {
            m->state = 3;
            if (m->prev_seq != 2)
                MobyBlendAnimation(m, 2, 0, scale_ticks(10));
        }
        break;
    case 3:
        if (!d->f8)
            goto tail;
        if (quartu_game_mode == 2)
            break;
        m->state = 4;
        if (m->prev_seq != 3)
            MobyBlendAnimation(m, 3, 0, scale_ticks(10));
        break;
    case 4:
        if (!(m->anim_flags & 2))
            break;
        if (d->f8 && quartu_game_mode != 2) {
            if (d->mode == 1) {
                m->state = 7;
                if (m->prev_seq != 5)
                    MobyBlendAnimation(m, 5, 0, scale_ticks(10));
            } else {
                if (m->prev_seq != 8)
                    MobyBlendAnimation(m, 8, 0, scale_ticks(10));
                m->state = 5;
            }
            break;
        }
        if (m->prev_seq != 8)
            MobyBlendAnimation(m, 8, 0, scale_ticks(10));
        m->state = 10;
        break;
    case 5:
        if ((m->anim_flags & 2) && m->prev_seq != 0)
            MobyBlendAnimation(m, 0, 0, scale_ticks(10));
        f = FastSin(d->f14);
        r = FastTweenColor(0x801414DC, 0x8004048C, (f + 1.0f) * 0.5f);
        m->glow_color = r;
        d->f14 = FastAddRots(d->f14, g_frame_time * 12.566371f);
        if (fast_dec_timer(d->blk18) == 0 && quartu_game_mode != 2)
            break;
        set_sentrybot_alarm_duration((char *)m, 0);
        d->f8 = 0;
        if (m->prev_seq != 8)
            MobyBlendAnimation(m, 8, 0, scale_ticks(10));
        m->state = 10;
        break;
    case 6:
        if (!d->f8)
            goto tail;
        m->state = 7;
        if (m->prev_seq != 5)
            MobyBlendAnimation(m, 5, 0, scale_ticks(10));
        break;
    case 7:
        if (!(m->anim_flags & 2))
            break;
        m->state = 8;
        if (m->prev_seq != 6)
            MobyBlendAnimation(m, 6, 0, scale_ticks(10));
        break;
    case 8: {
        float *pos = (float *)&m->pos;
        char *h2 = D_0013E633 + 0xE9D;
        float tmp[4];

        if (vec_distance_xy(pos, (float *)h2) < 16.0f && quartu_game_mode != 2 && fast_dec_timer(&d->c)) {
            qcopy(tmp, pos);
            tmp[2] = tmp[2] + 1.0f;
            if (coll_line(tmp, h2 + 0x50, 2, 0, 0) == 0 && activate_first_inactive_group_moby(d->idx, pos))
                d->c = d->d10;
        }
        r = fast_dec_timer(d->blk18);
        if (r != 0 || quartu_game_mode == 2) {
            set_sentrybot_alarm_duration((char *)m, 0);
            d->f8 = 0;
            m->state = 9;
            if (m->prev_seq != 7)
                MobyBlendAnimation(m, 7, 0, scale_ticks(10));
        }
        break;
    }
    case 9:
        if (!(m->anim_flags & 2))
            break;
        if (d->mode == 2) {
            m->state = 6;
            if (m->prev_seq != 4)
                MobyBlendAnimation(m, 4, 0, scale_ticks(10));
        } else {
            m->state = 10;
            if (m->prev_seq != 8)
                MobyBlendAnimation(m, 8, 0, scale_ticks(10));
        }
        break;
    case 10:
        if (!(m->anim_flags & 2))
            break;
        m->state = 2;
        if (m->prev_seq != 1)
            MobyBlendAnimation(m, 1, 0, scale_ticks(10));
        break;
    }
    if (d->f8)
        D_L15_00161B40_gp = 1;
tail:
    if (D_L15_00161B3C_gp != quartu_frame_count) {
        D_L15_00161B3C_gp = quartu_frame_count;
        update_sentrybot_alarm_effect(m);
        D_L15_00161B40_gp = 0;
    }
}
